<script setup>
import { ref, onMounted, onUnmounted } from 'vue'
import MainLayout from '@/Layouts/MainLayout.vue'
import { useTranslations } from '@/composables/useTranslations'
import HeaderHeroBgImage from "@/Components/headers/HeaderHero_bg_image.vue"
import BaseTitle from "@/Components/Base/BaseTitle.vue"
import TitleImageSplit from "@/Components/widgets/TitleImageSplit.vue"

defineOptions({
    layout: MainLayout
})

const { t } = useTranslations()
const windowWidth = ref(typeof window !== 'undefined' ? window.innerWidth : 1024)

const handleResize = () => {
    windowWidth.value = window.innerWidth
}

// ============================================
// Blob Morph Animatie
// ============================================

const blobPath = ref(null)
let morphInterval = null
let morphTimeout = null
let isBlob1 = true

const blob1 = "M402 636.125C320.257 524.094 106.833 479.292 -1 438.125V0.625C132 30.625 430.445 72.2328 744.445 64.7328C995.645 58.7328 1325.67 188.458 1442 249.125V987.625C1348 1022.52 1146.5 1039.62 868 1009.12C589.5 978.625 527.5 808.125 402 636.125Z"
const blob2 = "M375 677.915C259 593.415 107.833 488.082 0 446.915V9.41533C164 -14.0859 410 9.41533 745.445 73.5231C992.25 120.691 1326.67 197.249 1443 257.915V996.415C1349 1031.31 1243.5 1048.92 965 1018.42C686.5 987.915 547.099 803.28 375 677.915Z"

const currentBlob = ref(blob1)

const morphBlob = () => {
    currentBlob.value = isBlob1 ? blob2 : blob1
    isBlob1 = !isBlob1
}

onMounted(() => {
    window.addEventListener('resize', handleResize)

    // Start blob morph 1 (OverOnsBlob) na 1 seconde
    morphTimeout = setTimeout(() => {
        morphBlob()
        morphInterval = setInterval(morphBlob, 6000)
    }, 1000)
})

onUnmounted(() => {
    window.removeEventListener('resize', handleResize)

    // Cleanup blob morph 1
    if (morphTimeout) clearTimeout(morphTimeout)
    if (morphInterval) clearInterval(morphInterval)
})
</script>

